'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { CheckCircle2, XCircle, ClipboardCheck } from 'lucide-react';

export default function MarksApprovalPage() {
    const [pendingMarks, setPendingMarks] = useState<any[]>([]);

    const load = async () => {
        try {
            const res = await api.get<any[]>('/api/hod/marks/pending');
            if (res.success) setPendingMarks(res.data);
        } catch (e) { }
    };

    useEffect(() => { load(); }, []);

    const handleAction = async (subjectId: string, action: string) => {
        try {
            await api.patch(`/api/hod/marks/${subjectId}/action`, { action });
            load();
        } catch (e) { }
    };

    // Group by subject
    const grouped = pendingMarks.reduce((acc: Record<string, any[]>, m) => {
        if (!acc[m.subject_id]) acc[m.subject_id] = [];
        acc[m.subject_id].push(m);
        return acc;
    }, {});

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                Marks Approval
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Review and approve submitted marks</p>

            {Object.keys(grouped).length === 0 ? (
                <div className="card" style={{ textAlign: 'center', padding: 48, color: '#8a9aa2' }}>
                    <ClipboardCheck size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p>No pending marks for approval</p>
                </div>
            ) : Object.entries(grouped).map(([subjectId, marks]) => (
                <div key={subjectId} className="card" style={{ marginBottom: 16, padding: 24 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                        <div>
                            <div style={{ fontSize: 16, fontWeight: 700, color: '#142B34' }}>Subject: {subjectId}</div>
                            <div style={{ fontSize: 13, color: '#8a9aa2' }}>{marks.length} entries submitted</div>
                        </div>
                        <div style={{ display: 'flex', gap: 8 }}>
                            <button className="btn-primary btn-sm" onClick={() => handleAction(subjectId, 'approve')}>
                                <CheckCircle2 size={14} /> Approve
                            </button>
                            <button className="btn-danger" onClick={() => handleAction(subjectId, 'reject')}>
                                <XCircle size={14} /> Send Back
                            </button>
                        </div>
                    </div>
                    <div className="table-container">
                        <table>
                            <thead><tr><th>Student ID</th><th>Marks</th><th>Max</th><th>Status</th></tr></thead>
                            <tbody>
                                {marks.map((m: any) => (
                                    <tr key={m.id}>
                                        <td>{m.student_id}</td>
                                        <td style={{ fontWeight: 600 }}>{m.marks}</td>
                                        <td>{m.max_marks}</td>
                                        <td><span className="badge badge-warning">{m.status}</span></td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            ))}
        </div>
    );
}
